sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    // 1. If event parm 1 contains an email address, send directly to it
    if (event && event.parm1 && event.parm1.toString().indexOf('@') !== -1) {
        email.addAddress('to', event.parm1.toString());
        return;
    }
    // 2. Look up patient/consumer from current record
    if (current) {
        var recGr = null;
        if (current.patient && current.patient.getRefRecord) {
            recGr = current.patient.getRefRecord();
        } else if (current.consumer && current.consumer.getRefRecord) {
            recGr = current.consumer.getRefRecord();
        } else if (current.appointment && current.appointment.patient) {
            recGr = current.appointment.patient.getRefRecord();
        }
        if (recGr && recGr.isValidRecord()) {
            var patEmail = recGr.getValue('email');
            var patName = recGr.getValue('name') || recGr.getValue('first_name') || 'Valued Patient';
            if (patEmail) {
                email.addAddress('to', patEmail, patName);
            }
        }
    }
})(current, template, email, email_action, event);
